using System;using System.Linq;
namespace Synkoz {public static partial class GraphRules15 {
 static void ValidateR4(GraphNode15 n){if(n.PlacementR4==null||n.ActivationR4==null||n.MidiR4==null)throw new Exception("Réglages du module absents.");if(double.IsNaN(n.ImageOpacityR6)||double.IsInfinity(n.ImageOpacityR6)||n.ImageOpacityR6<0||n.ImageOpacityR6>100)throw new Exception("Opacité image invalide.");MidiFilterLogicR12.Validate(n.MidiR4);if(n.ActivationR4.FilterR12!=null)MidiFilterLogicR12.Validate(n.ActivationR4.FilterR12);if(n.ControlsR12==null||new[]{n.RotationR12,n.BrightnessR12,n.ContrastR12}.Any(v=>double.IsNaN(v)||double.IsInfinity(v))||n.ContrastR12<0)throw new Exception("Réglages vidéo invalides.");foreach(var b in n.ControlsR12){if(b.Input!=null&&b.Input.FilterR12!=null)MidiFilterLogicR12.Validate(b.Input.FilterR12);if(new[]{b.Min,b.Max,b.InputMin,b.InputMax,b.InputCenterR19,b.OutputCenterR19,b.AmplitudeR19,b.AttackPercentR19??0,b.ReleasePercentR19??0,b.AttackBeats,b.ReleaseBeats,b.LengthBeats,b.SmoothingBeatsR18}.Any(v=>double.IsNaN(v)||double.IsInfinity(v))||b.InputMin==b.InputMax||b.AttackPercentR19<0||b.AttackPercentR19>100||b.ReleasePercentR19<0||b.ReleasePercentR19>100||b.SmoothingBeatsR18<0||b.SmoothingBeatsR18>16||b.AttackBeats<0||b.ReleaseBeats<0||b.LengthBeats<=0)throw new Exception("Modulation vidéo invalide.");}var p=n.PlacementR4;if(new[]{p.X,p.Y,p.Width,p.Height,p.AngleR19,n.TriggerLevelR4,n.RearmR4,n.ThresholdAudioR4,n.RearmAudioR4,n.NoteLengthR4}.Any(v=>double.IsNaN(v)||double.IsInfinity(v))||p.Width<=0||p.Height<=0||p.Width>1000||p.Height>1000||Math.Abs(p.X)>500||Math.Abs(p.Y)>500)throw new Exception("Cadrage ou seuil invalide.");if(n.TriggerLevelR4<0||n.TriggerLevelR4>1||n.RearmR4<0||n.RearmR4>1||n.ThresholdAudioR4<0||n.ThresholdAudioR4>1||n.RearmAudioR4<0||n.RearmAudioR4>1||n.NoteLengthR4<=0||n.NoteLengthR4>60||n.NoteR4<0||n.NoteR4>127||n.ChannelR4<0||n.ChannelR4>31)throw new Exception("Conversion MIDI invalide.");if(n.ThresholdR4&&n.ActivationR4.Kind=="CC"&&n.RearmR4>=n.TriggerLevelR4)throw new Exception("Le réarmement doit être inférieur au seuil de déclenchement.");if(n.Kind==GraphKind15.AudioToMidiR4&&n.RearmAudioR4>=n.ThresholdAudioR4)throw new Exception("Le réarmement audio doit être inférieur au seuil.");if(n.ActivationR4.Channel< -1||n.ActivationR4.Channel>31||n.ActivationR4.CC< -1||n.ActivationR4.CC>127||n.ActivationR4.Notes==null||n.ActivationR4.Notes.Any(v=>v<0||v>127))throw new Exception("Sélection MIDI invalide.");}
}}
